from pathlib import Path
import ipaddress
TARGET='83.142.209.194'

def scan(path):
    hits=[]
    try:
        lines=Path(path).read_text().splitlines()[1:]
    except Exception as e:
        return [('error', str(e))]
    for line in lines:
        cols=line.split()
        remote=cols[2]
        ip_hex, port_hex = remote.split(':')
        if len(ip_hex)==8:
            ip=str(ipaddress.IPv4Address(bytes.fromhex(ip_hex)[::-1]))
        else:
            raw=bytes.fromhex(ip_hex)
            ip=str(ipaddress.IPv6Address(b''.join(raw[i:i+4][::-1] for i in range(0,16,4))))
        if ip == TARGET:
            hits.append(line)
    return hits
for path in ['/proc/net/tcp','/proc/net/udp','/proc/net/tcp6','/proc/net/udp6']:
    hits=scan(path)
    print(path, hits if hits else 'none')
